{
  "umf": "0.8.0",
  "id": "typed-search-e2e",
  "vocabularies": {
    "umf.access": {
      "version": "0.1.0"
    }
  },
  "modules": [
    {
      "id": "search",
      "namespace": "search",
      "elements": [
        {
          "id": "id",
          "name": "id",
          "kind": "field",
          "scalarType": "string",
          "cardinality": "one",
          "nullability": "required",
          "extensions": {}
        },
        {
          "id": "body",
          "name": "body",
          "kind": "field",
          "scalarType": "string",
          "cardinality": "one",
          "nullability": "required",
          "extensions": {}
        },
        {
          "id": "embedding",
          "name": "embedding",
          "kind": "field",
          "cardinality": "array",
          "nullability": "required",
          "extensions": {},
          "itemType": {
            "module": "search",
            "element": "component"
          },
          "facets": {
            "collectionSize": {
              "min": 3,
              "max": 3
            }
          }
        },
        {
          "id": "component",
          "name": "component",
          "kind": "field",
          "scalarType": "float",
          "cardinality": "one",
          "nullability": "required",
          "extensions": {}
        },
        {
          "id": "Doc",
          "name": "Doc",
          "kind": "record",
          "members": [
            {
              "module": "search",
              "element": "id"
            },
            {
              "module": "search",
              "element": "body"
            },
            {
              "module": "search",
              "element": "embedding"
            }
          ],
          "keys": [
            {
              "id": "doc-key",
              "fields": [
                {
                  "module": "search",
                  "element": "id"
                }
              ],
              "primary": true,
              "name": "Document identity"
            }
          ],
          "extensions": {}
        }
      ],
      "extensions": {
        "umf.access": {
          "views": [
            {
              "record": {
                "module": "search",
                "element": "Doc"
              },
              "selectedKey": {
                "module": "search",
                "element": "Doc",
                "key": "doc-key"
              },
              "fields": [
                {
                  "field": {
                    "module": "search",
                    "element": "id"
                  },
                  "row": {
                    "missing": false,
                    "null": false
                  },
                  "create": {
                    "missing": false,
                    "null": false
                  },
                  "mutable": false,
                  "generated": false
                },
                {
                  "field": {
                    "module": "search",
                    "element": "body"
                  },
                  "row": {
                    "missing": false,
                    "null": false
                  },
                  "create": {
                    "missing": false,
                    "null": false
                  },
                  "mutable": true,
                  "generated": false
                },
                {
                  "field": {
                    "module": "search",
                    "element": "embedding"
                  },
                  "row": {
                    "missing": false,
                    "null": false
                  },
                  "create": {
                    "missing": false,
                    "null": false
                  },
                  "mutable": true,
                  "generated": false
                },
                {
                  "field": {
                    "module": "search",
                    "element": "component"
                  },
                  "row": {
                    "missing": false,
                    "null": false
                  },
                  "create": {
                    "missing": false,
                    "null": false
                  },
                  "mutable": false,
                  "generated": false
                }
              ]
            }
          ],
          "columns": [],
          "search": [
            {
              "id": "text",
              "record": {
                "module": "search",
                "element": "Doc"
              },
              "kind": "keyword",
              "exactness": "exact",
              "filterable": [
                {
                  "module": "search",
                  "element": "id"
                },
                {
                  "module": "search",
                  "element": "body"
                }
              ],
              "keyword": {
                "source": [
                  {
                    "module": "search",
                    "element": "body"
                  }
                ],
                "ranking": {
                  "family": "implementation-defined"
                },
                "analyzer": {
                  "language": "english",
                  "stemming": true
                },
                "syntax": "plain"
              }
            },
            {
              "id": "semantic",
              "record": {
                "module": "search",
                "element": "Doc"
              },
              "kind": "vector",
              "exactness": "exact",
              "filterable": [
                {
                  "module": "search",
                  "element": "id"
                },
                {
                  "module": "search",
                  "element": "body"
                }
              ],
              "vector": {
                "field": {
                  "module": "search",
                  "element": "embedding"
                },
                "source": {
                  "module": "search",
                  "element": "body"
                },
                "model": {
                  "id": "fixture-embedder",
                  "version": "1"
                },
                "dimensions": 3,
                "metric": "cosine",
                "computedBy": "host"
              }
            }
          ],
          "searchBindings": [
            {
              "index": "text",
              "target": {
                "platform": "postgresql",
                "majorVersion": "18"
              },
              "native": "doc_text",
              "freshness": "transactional",
              "maxK": 100,
              "filtering": "complete"
            },
            {
              "index": "semantic",
              "target": {
                "platform": "postgresql",
                "majorVersion": "18"
              },
              "native": "doc_semantic",
              "freshness": "transactional",
              "maxK": 100,
              "filtering": "complete"
            }
          ]
        }
      }
    }
  ]
}
